import { pgTable, serial, text, integer, numeric, boolean, timestamp, index, uniqueIndex } from "drizzle-orm/pg-core";
import { sql } from "drizzle-orm";
import { createInsertSchema } from "drizzle-zod";
import { z } from "zod/v4";
import { bookingsTable } from "./bookings";

// Unique, human-readable invoice number generated by the DB for EVERY payment.
// Format: INV-YYMMDD-NNNNNN where NNNNNN is a sequential, ever-increasing counter
// drawn atomically from the `invoice_code_seq` Postgres sequence (so numbers go up
// in order, never random). The date prefix is kept; only the trailing code grows.
// Requires the sequence to exist in the DB:
//   CREATE SEQUENCE IF NOT EXISTS invoice_code_seq;
export const INVOICE_CODE_DEFAULT = sql`'INV-' || to_char(now(), 'YYMMDD') || '-' || lpad(nextval('invoice_code_seq')::text, 6, '0')`;

export const paymentsTable = pgTable("payments", {
  id: serial("id").primaryKey(),
  bookingId: integer("booking_id").notNull().references(() => bookingsTable.id, { onDelete: "cascade" }),
  amount: numeric("amount", { precision: 10, scale: 2 }).notNull(),
  method: text("method").notNull().default("cash"),
  status: text("status").notNull().default("completed"),
  reference: text("reference"),
  notes: text("notes"),
  isRefund: boolean("is_refund").notNull().default(false),
  confirmed: boolean("confirmed").notNull().default(false),
  confirmNote: text("confirm_note"),
  payerType: text("payer_type"),
  documentUrl: text("document_url"),
  // NOT unique: a mass/bulk payment is ONE invoice covering several ticket rows,
  // so all rows of a batch share a single invoice code. Single payments still get
  // their own distinct code from the sequence default.
  invoiceCode: text("invoice_code").default(INVOICE_CODE_DEFAULT),
  // Groups payments created together by a single mass/bulk payment so the ledger
  // and agent page can show them as one total line with a per-ticket breakdown.
  batchId: text("batch_id"),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
}, (t) => [
  index("idx_payments_booking_id").on(t.bookingId),
  index("idx_payments_status").on(t.status),
  index("idx_payments_batch_id").on(t.batchId),
  // Backstop against double-recording the SAME external (POK) card order when the
  // webhook AND the payment-return verify fire concurrently. Partial: only card
  // payments that carry a provider reference are constrained; manual cash/bank rows
  // (reference NULL) are unaffected.
  uniqueIndex("payments_booking_card_ref_uniq")
    .on(t.bookingId, t.reference)
    .where(sql`${t.reference} IS NOT NULL AND ${t.method} = 'card'`),
]);

export const insertPaymentSchema = createInsertSchema(paymentsTable).omit({ id: true, createdAt: true });
export type InsertPayment = z.infer<typeof insertPaymentSchema>;
export type Payment = typeof paymentsTable.$inferSelect;
